/**
 * Hilfe-Artikel zu „Qualitative Daten aus anderen Programmen und Teamarbeit“ (Erheben, Stufe 5, Paket 5F-a, 09.11.2026): REFI-QDA (.qdpx) einlesen, Fall-Code-Matrix und Quantifizieren,
 * Intercoder-Übereinstimmung auf Segmentebene, Gwets AC1, Konsens beim Kodieren, Pseudonymisieren und Anonymisieren, Projektdatei mit Passwort. Nur Deutsch und Englisch,
 * jeder Text ein Textpaar P(de, en). Alles in eigenen Worten. Sachlage nach docs/erheben/FACHBLATT-STUFE-5.md (Kernsätze und „Entscheide“) und den Belegen
 * BELEGE-UEBEREINSTIMMUNG.md (MAXQDA nach Handbuch MX22 nur zusammengefasst gelesen; O’Connor und Joffe 2020 gelesen), BELEGE-PSEUDONYM.md (Meyermann und Porzelt 2014 und
 * Qualiservice nur aus Suchzusammenfassungen; UK Data Service gelesen) und BELEGE-PASSWORT.md (age-Spezifikation, typage). Die Knopfnamen der Seite „Interviews“ stehen so im
 * Fachblatt (Paket 5E baut sie). Das AC1-Beispiel ist erfunden und von Hand nachgerechnet (Kappa -0,05, AC1 0,89, Brennan-Prediger 0,80).
 */
import { P } from '../i18n/laufzeit';
import { a, falsch, mitnehmen, type Roh } from './artikel-roh';

export const ROH_ERHEBEN_QUALITATIV: Roh[] = [
  // ---------------------------------------------------------------- 1. REFI-QDA (.qdpx) einlesen
  a('eh-qdpx-einlesen', 'verstehen', P('Wie bringe ich ein Projekt aus MAXQDA, ATLAS.ti oder NVivo mit? (REFI-QDA, .qdpx)', 'How do I bring in a project from MAXQDA, ATLAS.ti or NVivo? (REFI-QDA, .qdpx)'),
    P('REFI-QDA qdpx qde Austauschformat MAXQDA ATLAS.ti NVivo QualCoder Projekt einlesen importieren Dokumente Codes Segmente Kodierungen Kodierende Memos Fälle Variablen Positionen Meldungen zusammenführen Beispielprojekt', 'REFI-QDA qdpx qde exchange format MAXQDA ATLAS.ti NVivo QualCoder import project documents codes segments codings coders memos cases variables positions messages merge example project'),
    [
      { h: P('Kurz', 'In brief') },
      P('Statable liest Projekte aus MAXQDA, ATLAS.ti, NVivo und QualCoder, wenn sie als .qdpx-Datei vorliegen, und sagt dabei genau, was es nicht übernehmen konnte.', 'Statable reads projects from MAXQDA, ATLAS.ti, NVivo and QualCoder when they exist as a .qdpx file, and says exactly what it could not take over.'),
      { h: P('Was ist das?', 'What is it?') },
      P('REFI-QDA ist ein Austauschformat für qualitative Projekte. REFI steht für „Rotterdam Exchange Format Initiative“, QDA für „Qualitative Data Analysis“ (qualitative Datenanalyse). Programme wie MAXQDA, ATLAS.ti, NVivo und QualCoder können ein Projekt als Datei mit der Endung .qdpx speichern. Darin stecken die Texte, das Codebuch (die Liste der Codes), die Segmente (die markierten Textstellen), die Kodierungen (welcher Code an welcher Stelle), die Kodierenden, Memos, Fälle und Variablen.', 'REFI-QDA is an exchange format for qualitative projects. REFI stands for “Rotterdam Exchange Format Initiative”, QDA for “Qualitative Data Analysis”. Programs such as MAXQDA, ATLAS.ti, NVivo and QualCoder can save a project as a file ending in .qdpx. It holds the texts, the codebook (the list of codes), the segments (the marked passages), the codings (which code at which place), the coders, memos, cases and variables.'),
      P('REFI-QDA ist ein Austauschformat. Programme füllen es verschieden. Statable sagt Ihnen, was es nicht übernehmen konnte.', 'REFI-QDA is an exchange format. Programs fill it differently. Statable tells you what it could not take over.'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Exportieren Sie das Projekt im anderen Programm als REFI-QDA-Datei (.qdpx). Die genaue Stelle im Menü hängt vom Programm und seiner Fassung ab.', 'Export the project in the other program as a REFI-QDA file (.qdpx). The exact place in the menu depends on the program and its version.'),
        P('Öffnen Sie in Statable die Seite „Interviews“ (#interviews), Bereich „Projekt aus MAXQDA, ATLAS.ti, NVivo oder QualCoder einlesen (REFI-QDA, .qdpx)“, und wählen Sie „.qdpx einlesen“ (oder legen Sie die Datei dort ab).', 'Open the page “Interviews” (#interviews) in Statable, section “Read in a project from MAXQDA, ATLAS.ti, NVivo or QualCoder (REFI-QDA, .qdpx)”, and choose “Read .qdpx” (or drop the file there).'),
        P('Lesen Sie danach die Meldungsliste: Sie nennt, was gelesen wurde (Zahlen), was nicht, und welche Umrechnungen nötig waren. Nicht gelesen werden zum Beispiel Bilder, Flächen in PDF-Dateien und Zeitmarken in Ton und Video; Statable zählt sie und sagt es.', 'Then read the list of messages: it says what was read (numbers), what was not, and which conversions were needed. Pictures, areas in PDF files and time marks in audio and video are not read, for example; Statable counts them and says so.'),
        P('Wählen Sie, ob das Projekt zum vorhandenen hinzugefügt werden soll („Kodierungen zusammenführen“) oder es ersetzt. Beim Hinzufügen bleiben die Kodierenden getrennt, und gleiche Texte gelten als dasselbe Dokument.', 'Choose whether the project is added to the existing one (“merge codings”) or replaces it. When adding, the coders stay separate and identical texts count as the same document.')
      ] },
      { h: P('Worauf Statable achtet', 'What Statable checks') },
      { ul: [
        P('Positionen: Eine Textstelle ist eine Anfangs- und eine Endposition im Text. Programme zählen verschieden, zum Beispiel einen Zeilenumbruch als ein oder zwei Zeichen. Statable prüft jede Stelle gegen den Text und rechnet bei Bedarf um. Passt eine Stelle nicht in den Text, wird sie nicht übernommen und gemeldet. Nichts wird still verschoben.', 'Positions: a passage is a start and an end position in the text. Programs count differently, for example a line break as one or two characters. Statable checks every passage against the text and converts if needed. If a passage does not fit the text, it is not taken over and is reported. Nothing is shifted silently.'),
        P('Zusammenführen: Zwei Personen haben dieselben Interviews getrennt kodiert und wollen vergleichen. Statable erkennt gleiche Dokumente am zeichengleichen Text und gleiche Codes an der Kennung oder am gleichen Namenspfad (zum Beispiel „Belastung/Zeitdruck“).', 'Merging: two people coded the same interviews separately and want to compare. Statable recognises identical documents by identical text and identical codes by identifier or by the same name path (for example “Strain/Time pressure”).'),
        P('Sicherheit: Texte aus der Datei werden nie als Programmcode ausgeführt und nie als Seitentext eingesetzt.', 'Safety: texts from the file are never run as program code and never inserted as page markup.')
      ] },
      { h: P('Zum Ausprobieren', 'To try it') },
      P('Auf der Seite „Interviews“ lädt „Beispielprojekt mit zwei Kodierenden laden (erfunden)“ ein erfundenes Projekt mit drei Interviews zur Semesterplanung, drei Fällen und zwei Kodierenden. Es liegt auch als Datei im Ordner beispiel/qdpx der Statable-Seite (beispiel-de.qdpx, beispiel-en.qdpx, frei: CC0).', 'On the page “Interviews”, “Load example project with two coders (invented)” loads an invented project with three interviews about semester planning, three cases and two coders. It is also available as a file in the folder beispiel/qdpx of the Statable site (beispiel-de.qdpx, beispiel-en.qdpx, free: CC0).'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Eine .qdpx-Datei enthält alles, was im anderen Programm zu sehen war.', 'A .qdpx file contains everything that was visible in the other program.'),
        P('Das Format deckt vieles ab, aber nicht alles, und jedes Programm füllt es etwas anders. Darum zeigt Statable nach dem Einlesen, was fehlt: Prüfen Sie die Meldungen, bevor Sie rechnen.', 'The format covers a lot, but not everything, and every program fills it a little differently. That is why Statable shows what is missing after reading: check the messages before you calculate.')),
      mitnehmen(
        P('REFI-QDA (.qdpx) ist das gemeinsame Austauschformat qualitativer Programme; Statable liest Texte, Codes, Segmente, Kodierungen, Kodierende, Memos, Fälle und Variablen.', 'REFI-QDA (.qdpx) is the common exchange format of qualitative programs; Statable reads texts, codes, segments, codings, coders, memos, cases and variables.'),
        P('Jede Textstelle wird gegen den Text geprüft; was nicht passt oder fehlt, steht in der Meldungsliste.', 'Every passage is checked against the text; what does not fit or is missing appears in the list of messages.'),
        P('Beim Zusammenführen bleiben die Kodierenden getrennt, damit sich ihre Übereinstimmung später prüfen lässt.', 'When merging, the coders stay separate so that their agreement can be checked later.')
      )
    ], ['eh-fall-code-matrix', 'eh-uebereinstimmung-segmente', 'eh-kodierleitfaden', 'eh-faelle-interviews']),

  // ---------------------------------------------------------------- 2. Fall-Code-Matrix und Quantifizieren
  a('eh-fall-code-matrix', 'verstehen', P('Wie oft kommt welcher Code vor? (Fall-Code-Matrix, Quantifizieren)', 'How often does which code occur? (case-code matrix, quantitizing)'),
    P('Fall-Code-Matrix Quantifizieren Quantitizing Code Fall Häufigkeit Anzahl vorhanden 0 1 Einstufung Untercodes Überschneidung Segmentlänge Zitate Textspalten Datensatz p-Wert Mixed Methods evaluative Inhaltsanalyse', 'case-code matrix quantifying quantitizing code case frequency count present 0 1 rating sub-codes overlap segment length quotes text columns data set p-value mixed methods evaluative content analysis'),
    [
      { h: P('Kurz', 'In brief') },
      P('Aus kodierten Interviews wird eine Tabelle mit einer Zeile je Fall und einer Spalte je Code. Das ist hilfreich, hat aber klare Grenzen: 0 heißt nur „nicht kodiert“.', 'Coded interviews become a table with one row per case and one column per code. That is useful, but has clear limits: 0 only means “not coded”.'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Vier Interviews sind kodiert (erfunden). Die Tabelle nennt je Interview die vergebenen Codes, jede Nennung ist eine Textstelle. Füllen Sie von Hand zwei Matrizen mit einer Zeile je Fall und einer Spalte je Code: einmal „vorhanden“ (0 oder 1), einmal „Anzahl“. Beantworten Sie dann: (a) Was heißt die 0 bei Fall 4 und „Unterstützung“? (b) Darf man sagen, Zeitdruck sei in Fall 2 viermal so stark wie in Fall 1? (c) Würden Sie mit diesen vier Zeilen einen Test mit p-Wert rechnen? Lesen Sie erst danach die Lösung.', 'Four interviews are coded (invented). The table gives the codes assigned per interview, each mention is a passage. Fill in two matrices by hand with one row per case and one column per code: once “present” (0 or 1), once “count”. Then answer: (a) What does the 0 mean for case 4 and “Support”? (b) May one say that time pressure is four times as strong in case 2 as in case 1? (c) Would you run a test with a p-value on these four rows? Read the solution only afterwards.'),
      { tabelle: { kopf: [P('Fall', 'Case'), P('Dauer des Interviews', 'Length of the interview'), P('Vergebene Codes (je Nennung eine Textstelle)', 'Codes assigned (one passage per mention)')], zeilen: [
        ['1', P('45 Minuten', '45 minutes'), P('Planung, Planung, Planung, Zeitdruck', 'Planning, Planning, Planning, Time pressure')],
        ['2', P('20 Minuten', '20 minutes'), P('Planung, Zeitdruck, Zeitdruck, Zeitdruck, Zeitdruck', 'Planning, Time pressure, Time pressure, Time pressure, Time pressure')],
        ['3', P('50 Minuten', '50 minutes'), P('Unterstützung, Planung, Unterstützung, Planung', 'Support, Planning, Support, Planning')],
        ['4', P('15 Minuten', '15 minutes'), P('Zeitdruck (der Block zu Unterstützung wurde aus Zeitmangel nicht gefragt)', 'Time pressure (the block on support was not asked for lack of time)')]
      ] } },
      { h: P('Lösung', 'Solution') },
      { tabelle: { kopf: [P('Fall', 'Case'), P('Planung (vorhanden / Anzahl)', 'Planning (present / count)'), P('Zeitdruck (vorhanden / Anzahl)', 'Time pressure (present / count)'), P('Unterstützung (vorhanden / Anzahl)', 'Support (present / count)')], zeilen: [
        ['1', '1 / 3', '1 / 1', '0 / 0'],
        ['2', '1 / 1', '1 / 4', '0 / 0'],
        ['3', '1 / 2', '0 / 0', '1 / 2'],
        ['4', '0 / 0', '1 / 1', '0 / 0']
      ] } },
      { ol: [
        P('Die 0 heißt nur: in diesem Interview an keiner Stelle mit „Unterstützung“ kodiert. Hier weiß man sogar, warum: Der Block wurde nicht gefragt. Ob die Person Unterstützung erlebt hat, sagt die 0 nicht. Dasselbe gilt für die 0 bei Fall 1 und Fall 2: Auch dort ist unbekannt, ob es nicht vorkam, nicht erwähnt oder übersehen wurde.', 'The 0 only means: not coded with “Support” anywhere in this interview. Here one even knows why: the block was not asked. Whether the person experienced support, the 0 does not say. The same holds for the 0 in case 1 and case 2: there too it is unknown whether it did not occur, was not mentioned or was overlooked.'),
        P('Nein. Die Anzahl hängt davon ab, wie ausführlich die Person erzählt hat, wie lang das Interview war und wie fein kodiert wurde; Fall 2 hat sogar das kürzere Interview. Zählen ist außerdem eine Deutung: Was als eine Stelle gilt, entscheiden die Kodierenden. Ob der Zeitdruck größer ist, zeigen die Texte oder eine Einstufung (zum Beispiel niedrig, mittel, hoch).', 'No. The count depends on how detailed the person was, how long the interview was and how finely it was coded; case 2 even has the shorter interview. Counting is also an interpretation: what counts as one passage is decided by the coders. Whether the time pressure is greater is shown by the texts or a rating (for example low, medium, high).'),
        P('Eher nicht. Vier Fälle sind sehr wenige und meist gezielt ausgewählt, keine Zufallsstichprobe; ein p-Wert sagt dann wenig. Beschreiben Sie die Matrix lieber und gehen Sie bei Auffälligkeiten zu den Textstellen zurück. Statable zeigt bei so einer Auswertung einen entsprechenden Hinweis.', 'Rather not. Four cases are very few and usually chosen on purpose, not a random sample; a p-value then says little. Better describe the matrix and return to the passages when something stands out. Statable shows a corresponding note for such an analysis.')
      ] },
      P('Ausprobieren in Statable: Öffnen Sie die Seite „Interviews“ (#interviews), laden Sie das Beispielprojekt und wählen Sie den Bereich „Wie oft kommt welcher Code vor? (Fall-Code-Matrix, Quantifizieren)“. Vergleichen Sie „vorhanden“ und „Anzahl“; im Beispiel fehlt „Unterstützung“ in Fall 2 und „Wunsch“ in Fall 3 (0 heißt nicht kodiert). Übernehmen Sie die Matrix „als Datensatz“, benutzen Sie eine Spalte in einer Auswertung mit p-Wert und lesen Sie den Hinweis.', 'Trying it in Statable: open the page “Interviews” (#interviews), load the example project and choose the section “How often does which code occur? (case-code matrix, quantitising)”. Compare “present” and “count”; in the example “Support” is missing in case 2 and “Wish” in case 3 (0 means not coded). Take the matrix over “as data set”, use a column in an analysis with a p-value and read the note.'),
      { h: P('Was ist das?', 'What is it?') },
      P('Eine Fall-Code-Matrix ist eine Tabelle: eine Zeile je Fall (zum Beispiel je interviewter Person), eine Spalte je Code. Quantifizieren (englisch „quantitizing“) heißt, qualitative Befunde in Zahlen zu fassen, etwa „Code kommt vor“ als 1 oder die Zahl der Textstellen. Sandelowski, Voils und Knafl (2009) beschreiben das als übliches Vorgehen in Mixed-Methods-Studien (Verbindung qualitativer und quantitativer Methoden), mit klaren Grenzen.', 'A case-code matrix is a table: one row per case (for example per interviewed person), one column per code. Quantitizing means turning qualitative findings into numbers, for example “code occurs” as 1 or the number of passages. Sandelowski, Voils and Knafl (2009) describe it as a common approach in mixed-methods studies (combining qualitative and quantitative methods), with clear limits.'),
      { h: P('Drei Arten von Zellen', 'Three kinds of cells') },
      { ul: [
        P('Vorhanden (0/1): 1, wenn im Fall mindestens eine Kodierung mit dem Code steht, sonst 0. 0 heißt: nicht kodiert. Das ist nicht dasselbe wie „trifft nicht zu“.', 'Present (0/1): 1 if the case has at least one coding with the code, otherwise 0. 0 means: not coded. That is not the same as “does not apply”.'),
        P('Anzahl: die Zahl der Segmente mit dem Code im Fall. Wie oft etwas kodiert ist, hängt auch davon ab, wie lang das Interview war und wie fein kodiert wurde. Bei mehreren Kodierenden zählt dieselbe Stelle doppelt, darum wählt man eine Person.', 'Count: the number of segments with the code in the case. How often something is coded also depends on how long the interview was and how finely it was coded. With several coders the same passage counts twice, so choose one person.'),
        P('Einstufung aus Untercodes: Ein Obercode hat Stufen als Untercodes, zum Beispiel „Belastung“ mit „niedrig“, „mittel“, „hoch“. Sie ordnen jeder Stufe eine Zahl zu; die Zelle zeigt die Zahl. Fehlt ein Untercode, ist die Zelle fehlend (nicht 0); gibt es verschiedene Stufen im selben Fall, heißt sie „uneindeutig“. Bei einer evaluativen Inhaltsanalyse (jeder Fall wird eingestuft) übernimmt Statable Ihre Einstufung und zählt nichts.', 'Rating from sub-codes: a parent code has levels as sub-codes, for example “Strain” with “low”, “medium”, “high”. You assign a number to each level; the cell shows the number. If no sub-code is present the cell is missing (not 0); if different levels occur in the same case it reads “ambiguous”. In an evaluative content analysis (every case is rated) Statable takes over your rating and counts nothing.')
      ] },
      { h: P('Weitere Tabellen', 'More tables') },
      { ul: [
        P('Code-Überschneidungen: Wie oft liegen Segmente zweier Codes im selben Text übereinander (mindestens ein gemeinsames Zeichen)? Die Diagonale zeigt die Zahl der Segmente je Code.', 'Code overlaps: how often do segments of two codes lie on top of each other in the same text (at least one shared character)? The diagonal shows the number of segments per code.'),
        P('Segmentlängen: je Code Zahl, Mittelwert, Median, kleinster und größter Wert, in Zeichen und in Wörtern.', 'Segment lengths: per code the number, mean, median, smallest and largest value, in characters and in words.')
      ] },
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Seite „Interviews“ (#interviews), Bereich „Wie oft kommt welcher Code vor? (Fall-Code-Matrix, Quantifizieren)“: Art, Zeilen (Fälle oder Dokumente), Personen und Codes wählen. Die Hinweissätze stehen vor der Tabelle.', 'Page “Interviews” (#interviews), section “How often does which code occur? (case-code matrix, quantitizing)”: choose kind, rows (cases or documents), persons and codes. The notes stand before the table.'),
        P('„Als Datensatz übernehmen“ macht eine neue Tabelle mit einer Zeile je Fall, den Fallvariablen und einer Spalte je Code. So lässt sich damit weiterrechnen, etwa mit „Fälle vergleichen“.', '“Take over as data set” makes a new table with one row per case, the case variables and one column per code. You can then keep calculating, for example with “Compare cases”.'),
        P('Das Kästchen „Zitate als Textspalten übernehmen“ ist aus. Wenn Sie es einschalten, kommen die Textstellen als Spalten in den Datensatz; dann enthält das Projekt Interview-Texte, und Statable weist beim Speichern auf die Verschlüsselung hin (Hilfe „Projektdatei mit Passwort“).', 'The box “Take quotes over as text columns” is off. If you switch it on, the passages come into the data set as columns; the project then contains interview texts, and Statable points to encryption when saving (help “Project file with a password”).')
      ] },
      { h: P('Grenzen', 'Limits') },
      P('Wird eine Spalte aus einer Fall-Code-Matrix in einer Auswertung mit p-Wert benutzt, zeigt Statable den Satz: „Diese Zahlen kommen aus kodierten Interviews. Die Fälle sind meist gezielt ausgewählt und wenige; ein p-Wert sagt dann wenig.“ Maxwell (2010) betont, dass Zahlen in der qualitativen Forschung vor allem helfen, Aussagen über „viele“ oder „selten“ zu belegen, und keine Zufallsstichprobe ersetzen.', 'If a column from a case-code matrix is used in an analysis with a p-value, Statable shows the sentence: “These numbers come from coded interviews. The cases are usually chosen on purpose and few; a p-value then says little.” Maxwell (2010) stresses that in qualitative research numbers mainly help to support statements about “many” or “rare” and do not replace a random sample.'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Eine 0 in der Matrix heißt, dass das Thema im Fall keine Rolle spielt.', 'A 0 in the matrix means that the topic plays no role in the case.'),
        P('0 heißt nur: an keiner Stelle kodiert. Die Person kann es nicht erwähnt haben, nicht gefragt worden sein, oder die Kodierenden haben es übersehen.', '0 only means: not coded anywhere. The person may not have mentioned it, may not have been asked, or the coders may have missed it.')),
      { h: P('Quellen', 'Sources') },
      P('Sandelowski, M., Voils, C. I. & Knafl, G. (2009). On quantitizing. Journal of Mixed Methods Research, 3(3), 208-222. Maxwell, J. A. (2010). Using numbers in qualitative research. Qualitative Inquiry, 16(6), 475-482.', 'Sandelowski, M., Voils, C. I. & Knafl, G. (2009). On quantitizing. Journal of Mixed Methods Research, 3(3), 208-222. Maxwell, J. A. (2010). Using numbers in qualitative research. Qualitative Inquiry, 16(6), 475-482.'),
      mitnehmen(
        P('Eine Fall-Code-Matrix hat eine Zeile je Fall und eine Spalte je Code; Zellen sind „vorhanden“ (0/1), eine Anzahl oder eine Einstufung.', 'A case-code matrix has one row per case and one column per code; cells are “present” (0/1), a count or a rating.'),
        P('0 heißt „nicht kodiert“, nicht „trifft nicht zu“; Anzahlen hängen von Länge und Feinheit der Kodierung ab.', '0 means “not coded”, not “does not apply”; counts depend on length and fineness of the coding.'),
        P('Bei wenigen, gezielt ausgewählten Fällen sagt ein p-Wert wenig; Statable weist darauf hin.', 'With few, purposefully chosen cases a p-value says little; Statable points this out.')
      )
    ], ['eh-qdpx-einlesen', 'eh-faelle-interviews', 'eh-meta-inferenz', 'eh-projekt-passwort', 'eh-fall-kategorie-matrix']),

  // ---------------------------------------------------------------- 3. Intercoder-Übereinstimmung auf Segmentebene
  a('eh-uebereinstimmung-segmente', 'verstehen', P('Kodieren wir gleich? (Intercoder-Übereinstimmung auf Segmentebene)', 'Do we code the same? (intercoder agreement at segment level)'),
    P('Intercoder Übereinstimmung Segmentebene Dokumentebene Überlappung Schwelle 90 Prozent Brennan Prediger Kappa Abweichung Abweichungsliste Kodierleitfaden MAXQDA reflexive thematische Analyse Braun Clarke', 'intercoder agreement segment level document level overlap threshold 90 percent Brennan Prediger kappa disagreement list of disagreements coding guide MAXQDA reflexive thematic analysis Braun Clarke'),
    [
      { h: P('Kurz', 'In brief') },
      P('Zwei Personen haben denselben Text kodiert. Statable zählt, wie oft sie dasselbe getan haben, auf Dokumentebene und auf Segmentebene (mit einer Schwelle für die Überlappung), und zeigt jede Abweichung.', 'Two people coded the same text. Statable counts how often they did the same, at document level and at segment level (with a threshold for the overlap), and shows every disagreement.'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Zwei Personen haben denselben Interviewtext kodiert, mit den Codes „Planung“ und „Zeitdruck“. Die Daten sind erfunden. Die Tabelle nennt jede Stelle als Zeichenpositionen „von bis“; das Ende zählt nicht mit, die Länge ist also bis minus von. Prüfen Sie für jedes Paar mit gleichem Code die Überlappung (gemeinsame Zeichen geteilt durch Zeichen beider Stellen zusammen) und entscheiden Sie, ob das Paar bei einer Schwelle von 90 Prozent und bei 60 Prozent übereinstimmt. Zählen Sie dann aus, wie viele der 12 Einheiten (jede Stelle jeder Person ist eine Einheit) übereinstimmen, rechnen Sie den Anteil in Prozent aus und ordnen Sie jede übrige Einheit einer der drei Abweichungsarten zu. Lesen Sie erst danach die Lösung.', 'Two persons coded the same interview text with the codes “Planning” and “Time pressure”. The data are invented. The table gives each passage as character positions “from to”; the end does not count, so the length is to minus from. For each pair with the same code check the overlap (shared characters divided by the characters of both passages together) and decide whether the pair agrees at a threshold of 90 percent and at 60 percent. Then count how many of the 12 units (each passage of each person is a unit) agree, calculate the share in percent and assign each remaining unit to one of the three kinds of disagreement. Read the solution only afterwards.'),
      { tabelle: { kopf: [P('Nr.', 'No.'), P('Person A (Code, von bis)', 'Person A (code, from to)'), P('Person B (Code, von bis)', 'Person B (code, from to)'), P('Ihre Überlappung', 'Your overlap')], zeilen: [
        ['1', P('Planung 0 100', 'Planning 0 100'), P('Planung 0 80', 'Planning 0 80'), '?'],
        ['2', P('Zeitdruck 120 160', 'Time pressure 120 160'), P('Zeitdruck 122 160', 'Time pressure 122 160'), '?'],
        ['3', P('Planung 200 260', 'Planning 200 260'), P('Planung 205 265', 'Planning 205 265'), '?'],
        ['4', P('Zeitdruck 300 340', 'Time pressure 300 340'), P('Planung 300 340', 'Planning 300 340'), '?'],
        ['5', P('Planung 400 450', 'Planning 400 450'), P('(nichts)', '(nothing)'), '?'],
        ['6', P('(nichts)', '(nothing)'), P('Zeitdruck 500 530', 'Time pressure 500 530'), '?'],
        ['7', P('Planung 600 650', 'Planning 600 650'), P('Planung 600 650', 'Planning 600 650'), '?']
      ] } },
      { h: P('Lösung', 'Solution') },
      { ol: [
        P('Gemeinsam sind die Zeichen 0 bis 80, also 80 Zeichen; zusammen belegen beide 100. Überlappung 80 Prozent: bei 90 Prozent nein, bei 60 Prozent ja.', 'The shared characters are 0 to 80, so 80 characters; together both cover 100. Overlap 80 percent: at 90 percent no, at 60 percent yes.'),
        P('Gemeinsam sind 122 bis 160, also 38 Zeichen; zusammen belegen beide 120 bis 160, also 40. Überlappung 38 geteilt durch 40, das sind 95 Prozent: bei 90 und bei 60 Prozent ja.', 'The shared characters are 122 to 160, so 38 characters; together both cover 120 to 160, so 40. Overlap 38 divided by 40, that is 95 percent: at 90 and at 60 percent yes.'),
        P('Gemeinsam sind 205 bis 260, also 55 Zeichen; zusammen belegen beide 200 bis 265, also 65. Überlappung 55 geteilt durch 65, knapp 85 Prozent: bei 90 Prozent nein, bei 60 Prozent ja.', 'The shared characters are 205 to 260, so 55 characters; together both cover 200 to 265, so 65. Overlap 55 divided by 65, just under 85 percent: at 90 percent no, at 60 percent yes.'),
        P('Die Codes sind verschieden, also gibt es kein Gegenstück, egal bei welcher Schwelle. Art: gleiche Stelle, anderer Code (beide Einheiten).', 'The codes differ, so there is no counterpart, whatever the threshold. Kind: same place, different code (both units).'),
        P('Nur Person A hat hier kodiert. Art: nur eine Person.', 'Only person A coded here. Kind: only one person.'),
        P('Nur Person B hat hier kodiert. Art: nur eine Person.', 'Only person B coded here. Kind: only one person.'),
        P('Gleiche Stelle, gleicher Code: Überlappung 100 Prozent, bei jeder Schwelle ja.', 'Same place, same code: overlap 100 percent, yes at any threshold.')
      ] },
      P('Bei 90 Prozent stimmen die Paare 2 und 7 überein, das sind 4 der 12 Einheiten, also ein Drittel (33 Prozent). Abweichungen gibt es fünf: die Paare 1 und 3 (gleicher Code, aber Stelle verschieden), Paar 4 (gleiche Stelle, anderer Code) und die Stellen 5 und 6 (nur eine Person). Bei 60 Prozent stimmen die Paare 1, 2, 3 und 7 überein, das sind 8 von 12 Einheiten, zwei Drittel (67 Prozent), und es bleiben drei Abweichungen. Dieselben Stellen, zwei Schwellen, zwei Prozentzahlen: Nennen Sie darum immer die Schwelle.', 'At 90 percent pairs 2 and 7 agree, that is 4 of the 12 units, so one third (33 percent). There are five disagreements: pairs 1 and 3 (same code, place different), pair 4 (same place, different code) and the passages 5 and 6 (only one person). At 60 percent pairs 1, 2, 3 and 7 agree, that is 8 of 12 units, two thirds (67 percent), and three disagreements remain. The same passages, two thresholds, two percentages: so always state the threshold.'),
      P('Ausprobieren in Statable: Öffnen Sie die Seite „Interviews“ (#interviews) und laden Sie das Beispielprojekt mit zwei Kodierenden (erfunden). Wählen Sie im Bereich „Kodieren wir gleich? (Intercoder-Übereinstimmung)“ Kodiererin A und Kodierer B, rechnen Sie bei 90 Prozent und stellen Sie dann 60 Prozent ein: Der Anteil steigt, die Kodierungen sind dieselben. Wählen Sie „Einigung beginnen (Konsens)“ und entscheiden Sie drei Abweichungen mit je einer Begründung.', 'Trying it in Statable: open the page “Interviews” (#interviews) and load the example project with two coders (invented). In the section “Do we code the same? (intercoder agreement)” choose Coder A and Coder B, calculate at 90 percent and then set 60 percent: the share rises, the codings are the same. Choose “Start agreement (consensus)” and decide three disagreements with a reason each.'),
      { h: P('Was ist das?', 'What is it?') },
      P('Zwei Personen kodieren denselben Text getrennt. Die Intercoder-Übereinstimmung (Übereinstimmung zwischen Kodierenden) sagt, wie oft sie dasselbe getan haben. Statable rechnet auf zwei Ebenen. Auf Dokumentebene zählt je Dokument und Code nur, ob die Person den Code mindestens einmal vergeben hat (0 oder 1); daraus entstehen Prozent, Cohens Kappa, Brennan-Prediger, Krippendorffs Alpha und Gwets AC1. Auf Segmentebene zählt auch, ob die Textstellen zusammenpassen.', 'Two people code the same text separately. Intercoder agreement (agreement between coders) says how often they did the same. Statable calculates on two levels. At document level it only counts, per document and code, whether the person assigned the code at least once (0 or 1); from that come percent, Cohen’s kappa, Brennan-Prediger, Krippendorff’s alpha and Gwet’s AC1. At segment level it also counts whether the passages fit together.'),
      { h: P('Die Regel auf Segmentebene', 'The rule at segment level') },
      { ul: [
        P('Eine Einheit ist ein Segment mit einem Code (ein Segment mit zwei Codes ergibt zwei Einheiten), von beiden Personen zusammen.', 'A unit is a segment with a code (a segment with two codes gives two units), of both persons together.'),
        P('Die Überlappung zweier Textstellen ist der gemeinsame Text geteilt durch den Text beider zusammen, gezählt in Zeichen. Zwei Textstellen gelten als gleich, wenn sie sich zu mindestens 90 % decken. Die Schwelle ist wählbar (50 bis 100 % in 5er-Schritten).', 'The overlap of two passages is the shared text divided by the text of both together, counted in characters. Two passages count as the same if they coincide by at least 90 %. The threshold can be chosen (50 to 100 % in steps of 5).'),
        P('Eine Einheit stimmt überein, wenn die andere Person im selben Dokument denselben Code an einer Stelle mit genügender Überlappung vergeben hat. Das Ergebnis ist der Anteil übereinstimmender Einheiten, je Code und insgesamt.', 'A unit agrees if the other person assigned the same code in the same document at a place with enough overlap. The result is the share of agreeing units, per code and overall.'),
        P('Zufallsbereinigt wird nach Brennan und Prediger: (p minus 1/k) geteilt durch (1 minus 1/k), mit k als Zahl der gewählten Codes. Auf Segmentebene gibt es kein Feld „beide haben nichts kodiert“; darum rechnet Statable hier nicht mit Cohens Kappa.', 'Chance-corrected values follow Brennan and Prediger: (p minus 1/k) divided by (1 minus 1/k), with k as the number of chosen codes. At segment level there is no cell “both coded nothing”; that is why Statable leaves out Cohen’s kappa here.')
      ] },
      P('Beispiel (erfunden): Person A kodiert 100 Zeichen, Person B dieselben 100 Zeichen bis auf die letzten 20. Gemeinsam sind 80 Zeichen, zusammen belegen beide 100: Überlappung 80 %. Bei der Schwelle 90 % passen die zwei nicht zusammen, bei 60 % schon. Im Beispielprojekt ändert sich so der Anteil von 70,4 % (Schwelle 90 %) auf 85,2 % (Schwelle 60 %).', 'Example (invented): person A codes 100 characters, person B the same 100 characters except the last 20. 80 characters are shared, together both cover 100: overlap 80 %. At a threshold of 90 % the two do not fit, at 60 % they do. In the example project the share changes in this way from 70.4 % (threshold 90 %) to 85.2 % (threshold 60 %).'),
      { h: P('Die Abweichungsliste', 'The list of disagreements') },
      P('Alle Einheiten ohne Gegenstück stehen in einer Liste, in drei Arten: gleiche Stelle, anderer Code; gleicher Code, aber Stelle verschieden; nur eine Person hat hier kodiert. Je Eintrag sehen Sie Dokument, Text der Stelle und die Codes beider Personen. Sie ist die Grundlage für die Einigung (Hilfe „Konsens beim Kodieren“).', 'All units lacking a counterpart are in a list, in three kinds: same place, different code; same code, different place; only one person coded here. For each entry you see the document, the text of the passage and the codes of both persons. It is the basis for the agreement (help “Consensus when coding”).'),
      { h: P('Unterschied zu MAXQDA', 'Difference from MAXQDA') },
      P('Die Kernregel (Voreinstellung 90 %, Schnitt durch den gemeinsamen Bereich, gleicher Code nötig) entspricht dem Handbuch von MAXQDA (Fassung MX22); der Unterschied: MAXQDA zählt dort Segmente, Statable zählt Segment mal Code, und beim zufallsbereinigten Wert nimmt Statable die Zahl der gewählten Codes.', 'The core rule (default 90 %, intersection over the shared area, same code required) matches the MAXQDA manual (version MX22); the difference: MAXQDA counts segments there, Statable counts segment times code, and for the chance-corrected value Statable uses the number of chosen codes.'),
      { h: P('Wann Übereinstimmung sinnvoll ist', 'When agreement makes sense') },
      P('Übereinstimmung zu messen passt zu Verfahren mit festem Kodierleitfaden (zum Beispiel inhaltlich strukturierende Inhaltsanalyse). Bei reflexiver thematischer Analyse ist sie nicht sinnvoll; dort zählt das Gespräch über die Deutung (Braun und Clarke; O’Connor und Joffe 2020).', 'Measuring agreement fits methods with a fixed coding guide (for example content-structuring content analysis). With reflexive thematic analysis it makes no sense; there the conversation about interpretation counts (Braun and Clarke; O’Connor and Joffe 2020).'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Lesen Sie das Projekt mit zwei Kodierenden ein (Hilfe „REFI-QDA (.qdpx) einlesen“) oder laden Sie das Beispielprojekt.', 'Read in the project with two coders (help “REFI-QDA (.qdpx)”) or load the example project.'),
        P('Seite „Interviews“, Bereich „Kodieren wir gleich? (Intercoder-Übereinstimmung)“: Paar und Codes wählen, die Schwelle einstellen. Ergebnis und Abweichungsliste erscheinen als Tabellen.', 'Page “Interviews”, section “Do we code the same? (intercoder agreement)”: choose the pair and codes, set the threshold. Result and list of disagreements appear as tables.')
      ] },
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('90 % Übereinstimmung heißt, dass beide gleich kodiert haben.', '90 % agreement means that both coded the same.'),
        P('Es heißt, dass 90 % der Einheiten ein Gegenstück haben, und das hängt von der Schwelle ab: Mit 60 % sieht dasselbe Projekt deutlich besser aus. Nennen Sie darum immer die Schwelle und zeigen Sie die Abweichungen.', 'It means that 90 % of the units have a counterpart, and that depends on the threshold: with 60 % the same project looks clearly better. So always state the threshold and show the disagreements.')),
      { h: P('Quellen', 'Sources') },
      P('O’Connor, C. & Joffe, H. (2020). Intercoder reliability in qualitative research. International Journal of Qualitative Methods, 19 (frei zugänglich). MAXQDA-Handbuch, Seite „Intercoder Agreement“ (MX22), nur in der Zusammenfassung gelesen. Brennan, R. L. & Prediger, D. J. (1981). Coefficient kappa: some uses, misuses, and alternatives. Educational and Psychological Measurement, 41(3), 687-699.', 'O’Connor, C. & Joffe, H. (2020). Intercoder reliability in qualitative research. International Journal of Qualitative Methods, 19 (freely accessible). MAXQDA manual, page “Intercoder Agreement” (MX22), read in summary only. Brennan, R. L. & Prediger, D. J. (1981). Coefficient kappa: some uses, misuses, and alternatives. Educational and Psychological Measurement, 41(3), 687-699.'),
      mitnehmen(
        P('Auf Segmentebene stimmen zwei Textstellen überein, wenn sie denselben Code tragen und sich zu mindestens 90 % decken (einstellbar).', 'At segment level two passages agree if they carry the same code and coincide by at least 90 % (adjustable).'),
        P('Der zufallsbereinigte Wert nach Brennan und Prediger nimmt die Zahl der gewählten Codes als k; Cohens Kappa gibt es hier nicht.', 'The chance-corrected value after Brennan and Prediger takes the number of chosen codes as k; there is no Cohen’s kappa here.'),
        P('Die Abweichungsliste zeigt, wo die Uneinigkeit liegt; sie ist wichtiger als die Prozentzahl.', 'The list of disagreements shows where the disagreement lies; it is more important than the percentage.'),
        P('Bei reflexiver thematischer Analyse ist Übereinstimmung nicht sinnvoll.', 'With reflexive thematic analysis agreement makes no sense.')
      )
    ], ['eh-ac1', 'eh-konsens', 'eh-kodierleitfaden', 'intercoder', 'kappa']),

  // ---------------------------------------------------------------- 4. Gwets AC1
  a('eh-ac1', 'verstehen', P('Warum ist Kappa niedrig, obwohl fast alle gleich antworten? (Gwets AC1)', 'Why is kappa low although almost everyone answers the same? (Gwet’s AC1)'),
    P('Gwet AC1 Kappa-Paradox Übereinstimmung Zufallsübereinstimmung Prävalenz Intercoder Brennan Prediger irrCAC', 'Gwet AC1 kappa paradox agreement chance agreement prevalence intercoder Brennan Prediger irrCAC'),
    [
      { h: P('Kurz', 'In brief') },
      P('Gwets AC1 misst die Übereinstimmung von Kodierenden und bleibt sinnvoll, wenn fast alle in dieselbe Kategorie fallen, wo Kappa fälschlich niedrig ausfallen kann.', 'Gwet’s AC1 measures agreement between coders and stays meaningful when almost everyone falls into the same category, where kappa can wrongly come out low.'),
      { h: P('Was ist das?', 'What is it?') },
      P('Gwets AC1 ist ein Maß für die Übereinstimmung von Kodierenden bei Kategorien (Gwet 2008). Wie Kappa zieht es die Übereinstimmung ab, die der Zufall allein bringen würde. Es schätzt diesen Zufallsanteil aber anders und bleibt stabiler, wenn fast alle Fälle in dieselbe Kategorie fallen. Bei Kappa führt genau das zum „Kappa-Paradox“: Die Übereinstimmung ist hoch, Kappa aber niedrig oder sogar negativ.', 'Gwet’s AC1 is a measure of agreement between coders on categories (Gwet 2008). Like kappa it subtracts the agreement that chance alone would bring. But it estimates this chance share differently and stays more stable when almost all cases fall into the same category. With kappa exactly that leads to the “kappa paradox”: agreement is high, but kappa is low or even negative.'),
      P('Rechenweg: AC1 = (pa minus pe) geteilt durch (1 minus pe). pa ist der beobachtete Anteil der Übereinstimmung. pe ergibt sich aus den Anteilen der Kategorien: pe = Summe über alle Kategorien von Anteil mal (1 minus Anteil), geteilt durch (Zahl der Kategorien minus 1).', 'Calculation: AC1 = (pa minus pe) divided by (1 minus pe). pa is the observed share of agreement. pe follows from the shares of the categories: pe = sum over all categories of share times (1 minus share), divided by (number of categories minus 1).'),
      { h: P('Selbst nachrechnen', 'Calculate it yourself') },
      P('Die Zahlen sind erfunden. Zwei Personen beurteilen 100 Textstellen mit „ja“ oder „nein“. Beide sagen bei 90 Stellen „ja“; bei 5 sagt nur A „ja“, bei 5 nur B; „nein“ sagen nie beide. Dann ist pa = 0,90, und „ja“ hat im Mittel den Anteil 0,95. Cohens Kappa: erwartet 0,95 mal 0,95 plus 0,05 mal 0,05 = 0,905, also (0,90 minus 0,905) geteilt durch 0,095 = minus 0,05. AC1: pe = 0,95 mal 0,05 plus 0,05 mal 0,95 = 0,095, also (0,90 minus 0,095) geteilt durch 0,905 = 0,89. Brennan-Prediger (feste Annahme 1/2): (0,90 minus 0,5) geteilt durch 0,5 = 0,80.', 'The numbers are invented. Two people judge 100 passages as “yes” or “no”. Both say “yes” for 90 passages; for 5 only A says “yes”, for 5 only B; both never say “no”. Then pa = 0.90, and “yes” has a mean share of 0.95. Cohen’s kappa: expected 0.95 times 0.95 plus 0.05 times 0.05 = 0.905, so (0.90 minus 0.905) divided by 0.095 = minus 0.05. AC1: pe = 0.95 times 0.05 plus 0.05 times 0.95 = 0.095, so (0.90 minus 0.095) divided by 0.905 = 0.89. Brennan-Prediger (fixed assumption 1/2): (0.90 minus 0.5) divided by 0.5 = 0.80.'),
      P('Gleiche Übereinstimmung, aber minus 0,05 bei Kappa und 0,89 bei AC1: Das ist das Paradox. Kappa nimmt an, dass die Kodierenden „ja“ so oft vergeben, wie es ihre Häufigkeit nahelegt, und rechnet darum mit viel Zufall.', 'Same agreement, but minus 0.05 for kappa and 0.89 for AC1: that is the paradox. Kappa assumes that the coders give “yes” as often as their frequency suggests and therefore reckons with a lot of chance.'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ul: [
        P('In der Auswertung „Übereinstimmung“ (Kappa, Alpha, Brennan-Prediger) steht AC1 als zusätzliche Zeile, mit dem Satz: „AC1 bleibt auch dann sinnvoll, wenn fast alle in dieselbe Kategorie fallen (Kappa-Paradox).“ Das gilt für beliebig viele Kodierende und fehlende Angaben.', 'In the analysis “Agreement” (kappa, alpha, Brennan-Prediger) AC1 appears as an additional row, with the sentence: “AC1 stays meaningful even when almost everyone falls into the same category (kappa paradox).” It covers any number of coders and for missing values.'),
        P('Auf der Seite „Interviews“ gehört AC1 zum Ergebnis auf Dokumentebene (Hilfe „Intercoder-Übereinstimmung auf Segmentebene“). Gibt es nur eine einzige Kategorie, ist AC1 nicht berechenbar, und Statable zeigt keinen Wert.', 'On the page “Interviews” AC1 is part of the result at document level (help “Intercoder agreement at segment level”). If there is only a single category, AC1 cannot be calculated and Statable shows no value.')
      ] },
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('AC1 ist immer die bessere Wahl als Kappa.', 'AC1 is always the better choice than kappa.'),
        P('AC1 ist eine zusätzliche Sicht, kein Ersatz. Beide Maße gehören in den Bericht, mit der Prozent-Übereinstimmung und dem Hinweis, wie die Kategorien verteilt waren.', 'AC1 is an additional view, not a replacement. Both measures belong in the report, together with the percent agreement and a note on how the categories were distributed.')),
      { h: P('Quellen', 'Sources') },
      P('Gwet, K. L. (2008). Computing inter-rater reliability and its variance in the presence of high agreement. British Journal of Mathematical and Statistical Psychology, 61(1), 29-48. Gwet, K. L. (2014). Handbook of Inter-Rater Reliability (4. Aufl.). Die Werte in Statable stimmen mit dem R-Paket irrCAC (Funktion gwet.ac1.raw) überein.', 'Gwet, K. L. (2008). Computing inter-rater reliability and its variance in the presence of high agreement. British Journal of Mathematical and Statistical Psychology, 61(1), 29-48. Gwet, K. L. (2014). Handbook of Inter-Rater Reliability (4th ed.). The values in Statable agree with the R package irrCAC (function gwet.ac1.raw).'),
      mitnehmen(
        P('AC1 korrigiert wie Kappa für Zufall, schätzt ihn aber so, dass auch bei sehr ungleich verteilten Kategorien ein sinnvoller Wert bleibt.', 'AC1 corrects for chance like kappa but estimates it so that a meaningful value remains even with very unevenly distributed categories.'),
        P('Im Beispiel mit 90 Prozent Übereinstimmung ist Kappa etwa minus 0,05 und AC1 etwa 0,89.', 'In the example with 90 percent agreement kappa is about minus 0.05 and AC1 about 0.89.'),
        P('Berichten Sie Prozent, Kappa und AC1 nebeneinander und nennen Sie die Verteilung der Kategorien.', 'Report percent, kappa and AC1 side by side and state the distribution of the categories.')
      )
    ], ['kappa', 'intercoder', 'eh-uebereinstimmung-segmente']),

  // ---------------------------------------------------------------- 5. Konsens beim Kodieren
  a('eh-konsens', 'verstehen', P('Wie einigen wir uns, wenn wir verschieden kodiert haben? (Konsens beim Kodieren)', 'How do we agree when we coded differently? (consensus coding)'),
    P('Konsens Konsenskodierung Einigung Abweichung Abweichungsliste Begründung Kodierregel Codebuch Protokoll Word Team Kodierende Intercoder', 'consensus consensus coding agreement disagreement list of disagreements reasoning coding rule codebook protocol Word team coders intercoder'),
    [
      { h: P('Kurz', 'In brief') },
      P('Beim Konsens besprechen zwei Kodierende jede Abweichung, entscheiden mit Begründung und erhalten eine neue, gemeinsame Kodierung samt Protokoll als Word-Datei.', 'In consensus coding two coders discuss every disagreement, decide with a reason and get a new joint coding together with a protocol as a Word file.'),
      { h: P('Was ist das?', 'What is it?') },
      P('Konsens heißt hier: Zwei Kodierende besprechen jede Abweichung und einigen sich auf eine gemeinsame Kodierung. Das Ergebnis ist eine dritte, neue Kodierung „Konsens A/B“; die Kodierungen von A und B bleiben unverändert. Wichtig ist die Begründung: Sie macht die Entscheidung nachvollziehbar und kann als Kodierregel ins Codebuch (den Kodierleitfaden) wandern.', 'Consensus here means: two coders discuss every disagreement and agree on a joint coding. The result is a third, new coding “Consensus A/B”; the codings of A and B stay unchanged. The reasoning is important: it makes the decision traceable and can move into the codebook (the coding guide) as a coding rule.'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Berechnen Sie zuerst die Übereinstimmung für das Paar (Hilfe „Intercoder-Übereinstimmung auf Segmentebene“) und wählen Sie „Einigung beginnen (Konsens)“.', 'First calculate the agreement for the pair (help “Intercoder agreement at segment level”) and choose “Start agreement (consensus)”.'),
        P('Zu jeder Abweichung entscheiden Sie: „Kodierung von A übernehmen“, „Kodierung von B übernehmen“, „Beide Codes behalten“ (bei „gleiche Stelle, anderer Code“: beide Codes sind richtig) oder „Keine übernehmen (beide streichen)“. Bei „gleicher Code, aber Stelle verschieden“ heißt es „Grenzen von A übernehmen“, „Grenzen von B übernehmen“ oder „Beide Stellen behalten“. Bei „nur eine Person hat hier kodiert“ gibt es „Kodierung übernehmen“ oder „Nicht übernehmen“. Eine Begründung ist Pflicht, mindestens ein Wort.', 'For each disagreement you decide: “Take over the coding by A”, “Take over the coding by B”, “Keep both codes” (for “same passage, different code”: both codes are right) or “Take over neither (delete both)”. For “same code, passage differs” the choices are “Take over the boundaries of A”, “Take over the boundaries of B” or “Keep both passages”. For “only one person coded here” there are “Take over the coding by …” or “Do not take over”. A reason is required, at least one word.'),
        P('Mit „als Kodierregel übernehmen“ wird die Begründung mit Datum an die Regel des Codes im Codebuch angehängt.', 'With “take over as coding rule” the reasoning is added with the date to the rule of the code in the codebook.'),
        P('Der Fortschritt steht als Text („5 von 17 entschieden“). Offene Entscheidungen bleiben im Projekt gespeichert; Sie können aufhören und später weitermachen.', 'Progress is shown as text (“5 of 17 decided”). Open decisions stay saved in the project; you can stop and continue later.'),
        P('„Konsens anlegen“ erzeugt die neue Kodierung. „Protokoll als Word“ liefert ein Dokument mit Personen, Schwelle, der Übereinstimmung vorher, jeder Abweichung mit Entscheidung und Begründung, den übernommenen Regeln und der Übereinstimmung nachher.', '“Create consensus” produces the new coding. “Protocol as Word” delivers a document with persons, threshold, the agreement before, every disagreement with decision and reasoning, the rules taken over and the agreement afterwards.')
      ] },
      { h: P('Vorher und nachher richtig lesen', 'Reading before and after correctly') },
      P('Vorher heißt: A gegen B. Nachher heißt: A gegen Konsens und B gegen Konsens; das zeigt, wer wie oft nachgeben musste. Nach der Einigung ist die Übereinstimmung mit dem Konsens kein Gütemaß mehr, sondern zeigt, wie viel sich geändert hat. Wer sie als „verbesserte“ Übereinstimmung berichtet, täuscht die Leserschaft.', 'Before means: A against B. After means: A against consensus and B against consensus; this shows who had to give way how often. After the agreement, the match with the consensus is no longer a quality measure but shows how much has changed. Whoever reports it as “improved” agreement misleads the readers.'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Wenn wir uns einigen, ist die Kodierung zuverlässig.', 'If we agree, the coding is reliable.'),
        P('Einigung macht eine Kodierung gemeinsam verantwortet, nicht zuverlässig. Für die Zuverlässigkeit zählt die Übereinstimmung vor der Einigung. Das Protokoll zeigt, wie die Entscheidungen zustande kamen.', 'Agreeing makes a coding jointly owned, not reliable. For reliability the agreement before the discussion counts. The protocol shows how the decisions came about.')),
      mitnehmen(
        P('Konsens ist eine neue, dritte Kodierung; A und B bleiben unverändert.', 'Consensus is a new, third coding; A and B remain unchanged.'),
        P('Jede Entscheidung braucht eine Begründung, die als Kodierregel ins Codebuch übernommen werden kann.', 'Every decision needs a reason that can be taken into the codebook as a coding rule.'),
        P('Die Übereinstimmung mit dem Konsens ist kein Gütemaß, sie zeigt, wie viel sich geändert hat.', 'The match with the consensus is not a quality measure; it shows how much has changed.')
      )
    ], ['eh-uebereinstimmung-segmente', 'eh-kodierleitfaden', 'eh-qdpx-einlesen']),

  // ---------------------------------------------------------------- 6. Pseudonymisieren und Anonymisieren
  a('eh-pseudonymisieren', 'verstehen', P('Wie mache ich Personen in Interviews unkenntlich? (Pseudonymisieren und Anonymisieren)', 'How do I make people in interviews unrecognisable? (pseudonymising and anonymising)'),
    P('Pseudonymisieren Pseudonymisierung Anonymisieren Anonymisierung Namen ersetzen Zuordnungsliste indirekter Identifikator Hinweise Ort Beruf E-Mail Telefon Datum Postleitzahl Adresse IBAN Internetadresse Namensliste Bindestrich Meyermann Porzelt UK Data Service Datenschutz', 'pseudonymising pseudonymisation anonymising anonymisation replace names key list indirect identifier clues place occupation email phone date postcode address IBAN web address list of names hyphen Meyermann Porzelt UK Data Service data protection'),
    [
      { h: P('Kurz', 'In brief') },
      P('Statable ersetzt Namen und andere Angaben in Interviews durch Platzhalter, aber nur, was Sie in die Liste schreiben oder was eine Regel sicher trifft. Jeder Treffer wird einzeln bestätigt.', 'Statable replaces names and other details in interviews with placeholders, but only what you write into the list or what a rule hits reliably. Every match is confirmed individually.'),
      { h: P('Selbst machen', 'Do it yourself') },
      P('Dieses kurze Transkript ist erfunden. Finden Sie alle Angaben, die eine Person erkennbar machen können. Notieren Sie je Angabe, ob sie direkt oder indirekt erkennbar macht und wie Sie sie ersetzen würden. Überlegen Sie, welche davon Statable von selbst finden würde (aus der Namensliste oder durch eine Regel) und welche nicht. Es sind acht Angaben. Lesen Sie erst danach die Lösung.', 'This short transcript is invented. Find all details that can make a person recognisable. For each detail note whether it identifies directly or indirectly and how you would replace it. Think about which of them Statable would find by itself (from the list of names or by a rule) and which not. There are eight details. Read the solution only afterwards.'),
      { tabelle: { kopf: [P('Nr.', 'No.'), P('Beitrag (erfunden)', 'Contribution (invented)')], zeilen: [
        ['1', P('Interviewerin: Erzählen Sie doch mal, wie Sie zu Ihrem Beruf gekommen sind.', 'Interviewer: Tell me how you came to your profession.')],
        ['2', P('Befragte: Ich bin Anna Berger, und im Dorf kennt mich jeder. Ich bin die einzige Hebamme in Sankt Oswald, das hat nur dreihundert Einwohner.', 'Interviewee: I am Anna Berger, and everyone in the village knows me. I am the only midwife in Sankt Oswald, which has only three hundred inhabitants.')],
        ['3', P('Befragte: Angefangen habe ich am 3. März 2019 in der Praxis von Dr. Hofer. Mein Bruder Lukas hat damals gesagt, das halte ich keine zwei Jahre durch.', 'Interviewee: I started on 3 March 2019 at the practice of Dr Hofer. My brother Lukas said back then that I would not last two years.')],
        ['4', P('Befragte: Falls noch etwas fehlt, schreiben Sie mir an anna.berger@example.org.', 'Interviewee: If something is still missing, write to me at anna.berger@example.org.')]
      ] } },
      { h: P('Lösung', 'Solution') },
      { tabelle: { kopf: [P('Angabe', 'Detail'), P('Art', 'Kind'), P('Ersatz (Vorschlag)', 'Replacement (suggestion)'), P('Findet Statable es?', 'Does Statable find it?')], zeilen: [
        [P('Anna Berger', 'Anna Berger'), P('direkt (Name)', 'direct (name)'), '[Person 1]', P('Nur aus Ihrer Liste (Art Person)', 'Only from your list (kind person)')],
        [P('Sankt Oswald', 'Sankt Oswald'), P('direkt (sehr genauer Ort)', 'direct (very precise place)'), P('[Ort 1]', '[Place 1]'), P('Nur aus Ihrer Liste (Art Ort)', 'Only from your list (kind place)')],
        [P('dreihundert Einwohner', 'three hundred inhabitants'), P('indirekt (erst mit Beruf und Ort)', 'indirect (only with occupation and place)'), P('[sehr kleiner Ort]', '[very small place]'), P('Nein, das müssen Sie selbst lesen', 'No, you must read it yourself')],
        [P('einzige Hebamme', 'only midwife'), P('indirekt (seltener Beruf in kleinem Ort)', 'indirect (rare occupation in a small place)'), P('[Beruf im Gesundheitsbereich]', '[occupation in health care]'), P('Nein, das müssen Sie selbst lesen', 'No, you must read it yourself')],
        [P('3. März 2019', '3 March 2019'), P('indirekt (genauer Zeitpunkt)', 'indirect (precise point in time)'), P('[Jahr]', '[year]'), P('Ja, mit der Regel „Datum“ (der Treffer ist zunächst nicht angekreuzt)', 'Yes, with the rule “date” (the match is not ticked at first)')],
        [P('Dr. Hofer', 'Dr Hofer'), P('direkt (Name, zugleich Arbeitsstelle)', 'direct (name, also workplace)'), P('[Praxis 1]', '[practice 1]'), P('Nur aus Ihrer Liste (Eintrag „Hofer“)', 'Only from your list (entry “Hofer”)')],
        [P('Bruder Lukas', 'brother Lukas'), P('direkt (Name einer dritten Person)', 'direct (name of a third person)'), P('[Bruder]', '[brother]'), P('Nur aus Ihrer Liste (Art Person)', 'Only from your list (kind person)')],
        [P('anna.berger@example.org', 'anna.berger@example.org'), P('direkt (E-Mail)', 'direct (email)'), P('[E-Mail]', '[email]'), P('Ja, mit der Regel „E-Mail“', 'Yes, with the rule “email”')]
      ] } },
      P('Zusammengezählt: Zwei Angaben treffen Regeln (E-Mail und Datum, das Datum erst nach dem Ankreuzen), vier findet Statable nur, wenn Sie sie in die Liste schreiben, zwei findet keine Regel. Gerade die indirekten Angaben verraten die Person im Zusammenspiel: „einzige Hebamme“ in einem Ort mit dreihundert Einwohnern ist auch ohne Namen erkennbar. Darum ist das Transkript nach dem Ersetzen der Namen höchstens pseudonymisiert.', 'Added up: two details hit rules (email and date, the date only after ticking it), four Statable finds only if you write them into the list, two are found by no rule. The indirect details in particular give the person away in combination: “only midwife” in a place of three hundred inhabitants is recognisable even without a name. So after the names are replaced the transcript is at best pseudonymised.'),
      P('Ausprobieren in Statable: Öffnen Sie die Seite „Interviews“ (#interviews), lesen Sie das Beispielinterview ein (Abschnitt „Transkripte“) und gehen Sie zum Bereich „Personen unkenntlich machen (Pseudonymisieren)“. Tragen Sie Namen mit ihrer Art in die Liste ein, wählen Sie die Regeln, suchen Sie die Treffer und bestätigen Sie jeden einzeln. Speichern Sie die Zuordnungsliste und bewahren Sie sie getrennt von den Daten auf.', 'Trying it in Statable: open the page “Interviews” (#interviews), read in the example interview (section “Transcripts”) and go to the section “Make persons unrecognisable (pseudonymising)”. Enter names with their kind into the list, choose the rules, find the matches and confirm each one individually. Save the key list and keep it apart from the data.'),
      { h: P('Was ist das?', 'What is it?') },
      P('Pseudonymisieren heißt, Namen und andere Angaben durch Platzhalter zu ersetzen („Anna“ wird „[Person 1]“). Eine Zuordnungsliste (Platzhalter und Klartext) kann die Personen wieder erkennbar machen, darum bleiben solche Daten personenbezogen. Anonymisieren heißt, so viel zu entfernen oder zu verallgemeinern, dass niemand mehr erkennbar ist, auch nicht über die Zuordnungsliste. Direkte Kennzeichen sind Namen, Adressen, E-Mail, Telefon. Ein indirekter Identifikator ist eine Angabe, die erst zusammen mit anderen erkennbar macht, etwa ein seltener Beruf in einem kleinen Ort oder ein einmaliges Erlebnis (UK Data Service).', 'Pseudonymising means replacing names and other details with placeholders (“Anna” becomes “[Person 1]”). A key list (placeholder and original) can make the persons recognisable again, which is why such data stay personal data. Anonymising means removing or generalising so much that nobody is recognisable any more, not even via the key list. Direct identifiers are names, addresses, email, phone. An indirect identifier is a detail that only makes someone recognisable together with others, such as a rare occupation in a small town or a unique experience (UK Data Service).'),
      { h: P('Was Statable findet und was nicht', 'What Statable finds and what not') },
      { ul: [
        P('Statable findet Namen nur, wenn Sie sie in die Liste schreiben (Person, Ort, Organisation, Sonstiges). Die Sprechernamen der Transkripte kommen von selbst in die Liste der Personen. Gesucht wird ganzwortweise, ohne Rücksicht auf Groß- und Kleinschreibung, mit deutscher Genitiv-Endung „s“.', 'Statable finds names only if you write them into the list (person, place, organisation, other). The speaker names of the transcripts go into the list of persons by themselves. The search is by whole words, regardless of case, with the German genitive ending “s”.'),
        P('Eine automatische Namenserkennung gibt es nicht: Ein Modell wäre groß und für deutsche Texte unzuverlässig. Lesen Sie das Transkript darum trotzdem einmal ganz durch.', 'There is no automatic name recognition: a model would be large and unreliable for German texts. So read the transcript through once in full anyway.'),
        P('Namen mit Bindestrich wie „Anna-Lena“ trifft „Anna“ nicht, weil der Bindestrich beide Teile verbindet. Schreiben Sie „Anna-Lena“ als eigenen Eintrag in die Liste.', 'Names with a hyphen such as “Anna-Lena” are not hit by “Anna”, because the hyphen joins both parts. Write “Anna-Lena” as its own entry in the list.'),
        P('Regeln (einzeln abwählbar): E-Mail, Telefon, Datum, Postleitzahl, Adresse, Internetadresse, IBAN. Die Regeln für Datum, Postleitzahl und Adresse treffen öfter falsch; ihre Treffer sind darum zunächst nicht angekreuzt.', 'Rules (each can be switched off): email, phone, date, postcode, address, web address, IBAN. The rules for date, postcode and address are wrong more often; their matches are therefore not ticked at first.'),
        P('Indirekte Hinweise wie „Lehrerin an der einzigen Schule des Dorfes“ erkennt keine Regel. Das müssen Sie selbst lesen und umschreiben („Lehrerin“ wird „[Beruf im Bildungsbereich]“).', 'Indirect clues such as “teacher at the only school in the village” are recognised by no rule. You must read and rephrase these yourself (“teacher” becomes “[occupation in education]”).')
      ] },
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ol: [
        P('Seite „Interviews“ (#interviews), Bereich „Personen unkenntlich machen (Pseudonymisieren)“: Namen mit Art in die Liste eintragen („Hinzufügen“), Regeln wählen, „Treffer suchen“.', 'Page “Interviews” (#interviews), section “Make persons unrecognisable (pseudonymising)”: enter names with their kind in the list (“Add”), choose rules, “Find matches”.'),
        P('Jeder Treffer wird einzeln bestätigt (Kästchen vor dem Treffer; „Alle Treffer dieser Art annehmen“ kreuzt eine ganze Gruppe an). Gleicher Klartext bekommt im ganzen Projekt denselben Platzhalter; Platzhalter dürfen Sie umbenennen.', 'Every match is confirmed individually (box in front of the match; “Accept all matches of this type” ticks a whole group). The same original text gets the same placeholder across the whole project; you may rename placeholders.'),
        P('„Ersetzen“ fragt vorher nach, wie viele Stellen in wie vielen Dokumenten ersetzt werden. Bis zum Speichern können Sie den Lauf rückgängig machen. Markierte Textstellen (Segmente) und Transkript-Abschnitte verschieben sich mit, damit die Kodierungen an der richtigen Stelle bleiben.', '“Replace” first asks how many places in how many documents will be replaced. Until you save you can undo the run. Marked passages (segments) and transcript sections move along so that the codings stay in the right place.'),
        P('„Zuordnungsliste speichern“ legt eine eigene CSV-Datei an (Ersatz, Klartext, Art, Zahl der Stellen). Sie ist nie in der Projektdatei.', '“Save key list” creates a separate CSV file (replacement, original, kind, count). It is never part of the project file.')
      ] },
      P('Bewahren Sie die Zuordnungsliste getrennt von den Daten auf, am besten verschlüsselt. Wer beide hat, kann die Personen wieder erkennen. Ohne Liste lässt sich die Zuordnung nicht wiederherstellen.', 'Keep the key list apart from the data, preferably encrypted. Whoever has both can recognise the persons again. Without the list the assignment cannot be restored.'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Wenn alle Namen ersetzt sind, sind die Interviews anonym.', 'If all names are replaced, the interviews are anonymous.'),
        P('Dann sind sie höchstens pseudonymisiert. Berufe, Orte, Zeitangaben und besondere Erlebnisse können zusammen Personen erkennbar machen. Ob Daten anonym sind, hängt davon ab, wer sie mit welchem Zusatzwissen lesen könnte.', 'Then they are at best pseudonymised. Occupations, places, times and special experiences can together make persons recognisable. Whether data are anonymous depends on who might read them with what additional knowledge.')),
      { h: P('Quellen', 'Sources') },
      P('UK Data Service: Anonymisation for text data (frei zugänglich, gelesen). Meyermann, A. & Porzelt, M. (2014). Hinweise zur Anonymisierung von qualitativen Daten. forschungsdaten bildung informiert, 1 (frei zugänglich; nur in Zusammenfassungen gelesen). Keine Rechtsberatung.', 'UK Data Service: Anonymisation for text data (freely accessible, read). Meyermann, A. & Porzelt, M. (2014). Hinweise zur Anonymisierung von qualitativen Daten. forschungsdaten bildung informiert, 1 (freely accessible; read in summaries only). Not legal advice.'),
      mitnehmen(
        P('Pseudonymisieren ersetzt Namen durch Platzhalter, die Zuordnungsliste kann sie zurückführen; Anonymisieren muss auch indirekte Hinweise beseitigen.', 'Pseudonymising replaces names with placeholders, the key list can trace them back; anonymising must also remove indirect clues.'),
        P('Statable findet Namen nur aus Ihrer Liste und bestätigt jeden Treffer einzeln; Bindestrich-Namen kommen als eigener Eintrag in die Liste.', 'Statable finds names only from your list and confirms each match individually; hyphenated names go into the list as their own entry.'),
        P('Die Zuordnungsliste wird getrennt von den Daten aufbewahrt.', 'The key list is kept apart from the data.')
      )
    ], ['eh-anonym-pseudonym', 'eh-datenschutz-ohne-server', 'eh-projekt-passwort']),

  // ---------------------------------------------------------------- 7. Projektdatei mit Passwort
  a('eh-projekt-passwort', 'verstehen', P('Wie schütze ich die Projektdatei mit einem Passwort? (Verschlüsselung, Format age)', 'How do I protect the project file with a password? (encryption, age format)'),
    P('Passwort Projektdatei verschlüsseln Verschlüsselung age scrypt statable Interview Transkripte persönliche Daten Datenschutz Passwort vergessen Autospeichern Schlüsselpaar Antwortdatei', 'password project file encrypt encryption age scrypt statable interview transcripts personal data data protection forgotten password autosave key pair answer file'),
    [
      { h: P('Kurz', 'In brief') },
      P('Interview-Texte sind persönliche Daten. Darum kann Statable die Projektdatei mit einem Passwort verschlüsseln; ohne das Passwort kann niemand sie öffnen.', 'Interview texts are personal data. That is why Statable can encrypt the project file with a password; without the password nobody can open it.'),
      { h: P('Was ist das?', 'What is it?') },
      P('Verschlüsseln heißt, eine Datei so zu verändern, dass sie ohne das Passwort nicht lesbar ist. Statable benutzt dafür das offene Format „age“ mit einem Passwort (Schlüsselableitung scrypt, eine bewusst langsame Rechnung, die Raten erschwert). Innen liegt die unveränderte Projektdatei mit der Endung .statable. Sie können die Datei auch mit dem Programm „age“ entschlüsseln, Statable ist also nicht die einzige Tür.', 'Encrypting means changing a file so that it cannot be read without the password. For this Statable uses the open format “age” with a password (key derivation scrypt, a deliberately slow calculation that makes guessing harder). Inside lies the unchanged project file with the ending .statable. You can also decrypt the file with the program “age”, so Statable is not the only door.'),
      { h: P('So geht es in Statable', 'How it works in Statable') },
      { ul: [
        P('Beim Speichern: Enthält das Projekt Interview-Texte, Memos, Segmente oder Zitate, fragt Statable einmal je Sitzung: „Diese Projektdatei enthält Interview-Texte oder Zitate. Das sind persönliche Daten. Mit Passwort verschlüsseln?“ Sie wählen „Mit Passwort speichern“ oder „Ohne Passwort speichern“. Im Projektmenü gibt es „Mit Passwort speichern …“ auch jederzeit.', 'When saving: if the project contains interview texts, memos, segments or quotes, Statable asks once per session: “This project file contains interview texts or quotes. These are personal data. Encrypt with a password?” You choose “Save with a password” or “Save without a password”. The project menu also offers “Save with a password …” at any time.'),
        P('Passwort setzen: zweimal eingeben, mindestens 8 Zeichen, keine weiteren Regeln. Ohne Passwort kann niemand die Datei öffnen, auch Statable nicht. Schreiben Sie es an einen sicheren Ort. Statable speichert das Passwort nicht, auch nicht im Browser, und legt keinen Hinweis in die Datei.', 'Setting the password: enter it twice, at least 8 characters, no further rules. Without the password nobody can open the file, not even Statable. Write it down in a safe place. Statable does not store the password, not even in the browser, and puts no hint into the file.'),
        P('Beim Öffnen: Erkennt Statable eine verschlüsselte Datei, fragt es nach dem Passwort. Bei einem falschen Passwort steht „Das Passwort passt nicht.“, das Feld bleibt, und Sie können es beliebig oft neu versuchen. „Abbrechen“ öffnet nichts.', 'When opening: if Statable recognises an encrypted file it asks for the password. With a wrong password it says “The password does not match.”, the field stays, and you can try again as often as you like. “Cancel” opens nothing.'),
        P('Nach dem Speichern mit Passwort fragt Statable bei jedem weiteren Speichern erneut nach dem Passwort und schreibt nicht mehr von selbst in die Datei (das Autospeichern in die Datei ruht, damit nie unverschlüsselt geschrieben wird).', 'After saving with a password Statable asks for the password again at every further save and no longer writes to the file by itself (autosave to the file rests so that nothing is ever written unencrypted).'),
        P('Ist eine Datei mit einem Schlüssel statt mit einem Passwort verschlüsselt (zum Beispiel eine Antwortdatei aus einer Erhebung), sagt Statable es und verweist auf „Antworten einlesen“.', 'If a file is encrypted with a key instead of a password (for example an answer file from a survey), Statable says so and points to “Read in answers”.')
      ] },
      { h: P('Was das Passwort nicht schützt', 'What the password does not protect') },
      P('Das automatische Speichern im Browser bleibt wie bisher auf dem Gerät der Person und ist nicht durch dieses Passwort geschützt. Auf einem fremden oder gemeinsam genutzten Gerät sollten Sie die Browserdaten danach löschen.', 'Automatic saving in the browser stays on the person’s device as before and is not protected by this password. On a foreign or shared device you should delete the browser data afterwards.'),
      { h: P('Stimmt nicht - so ist es', 'Not true - this is how it is') },
      falsch(P('Statable kann ein vergessenes Passwort zurücksetzen.', 'Statable can reset a forgotten password.'),
        P('Es gibt kein Zurücksetzen: Das Passwort wird nirgends gespeichert, und es gibt keine Hintertür. Wer es vergisst, verliert die Datei. Legen Sie darum eine unverschlüsselte Sicherung nur an einem Ort ab, den Sie ohnehin gut schützen.', 'There is no reset: the password is stored nowhere and there is no back door. Whoever forgets it loses the file. So keep an unencrypted backup only in a place that you protect well anyway.')),
      mitnehmen(
        P('Interview-Texte und Zitate sind persönliche Daten; die Projektdatei lässt sich mit Passwort verschlüsseln (Format age).', 'Interview texts and quotes are personal data; the project file can be encrypted with a password (age format).'),
        P('Mindestens 8 Zeichen; ohne das Passwort kann niemand die Datei öffnen, auch Statable nicht.', 'At least 8 characters; without the password nobody can open the file, not even Statable.'),
        P('Das automatische Speichern im Browser ist davon getrennt und bleibt auf dem Gerät.', 'Automatic saving in the browser is separate and stays on the device.')
      )
    ], ['eh-pseudonymisieren', 'eh-datenschutz-ohne-server', 'eh-qdpx-einlesen'])
];
